statements:
CREATE TABLE IF NOT EXISTS drive_accounts (
      subject TEXT PRIMARY KEY, email TEXT NOT NULL COLLATE NOCASE UNIQUE,
      refresh_token TEXT NOT NULL, access_token TEXT, expires_at INTEGER
    );
    CREATE TABLE IF NOT EXISTS drive_pending (
      state_hash TEXT PRIMARY KEY, verifier TEXT NOT NULL, redirect_uri TEXT NOT NULL,
      client_id TEXT NOT NULL, expires_at INTEGER NOT NULL
    );

CREATE TABLE IF NOT EXISTS docs_creations (
      operation_id TEXT PRIMARY KEY, subject TEXT NOT NULL, receipt TEXT NOT NULL
    );

CREATE TABLE drive_sharing_operations (
      operation_id TEXT PRIMARY KEY, subject TEXT NOT NULL, file_id TEXT NOT NULL,
      state TEXT NOT NULL, receipt TEXT NOT NULL
    );
    CREATE UNIQUE INDEX drive_sharing_active_file ON drive_sharing_operations(file_id)
      WHERE state IN ('reviewing','writing','uncertain');

CREATE TABLE drive_formatting_operations (
      operation_id TEXT PRIMARY KEY, subject TEXT NOT NULL, document_id TEXT NOT NULL,
      state TEXT NOT NULL, receipt TEXT NOT NULL
    );
    CREATE UNIQUE INDEX drive_formatting_active_document ON drive_formatting_operations(document_id)
      WHERE state IN ('reviewing','writing','uncertain');

CREATE TABLE drive_sheets_edits (
  operation_id TEXT PRIMARY KEY, subject TEXT NOT NULL, spreadsheet_id TEXT NOT NULL,
  state TEXT NOT NULL, receipt TEXT NOT NULL
);
CREATE UNIQUE INDEX drive_sheets_edit_active ON drive_sheets_edits(spreadsheet_id)
  WHERE state IN ('reviewing','writing','uncertain');

CREATE TABLE drive_filing_operations (
  operation_id TEXT PRIMARY KEY, subject TEXT NOT NULL, resource TEXT NOT NULL,
  state TEXT NOT NULL, receipt TEXT NOT NULL
);
CREATE UNIQUE INDEX drive_filing_active_resource ON drive_filing_operations(resource)
  WHERE state IN ('reviewing','writing','uncertain');

CREATE TABLE docs_image_operations (
  operation_id TEXT PRIMARY KEY, subject TEXT NOT NULL, document_id TEXT NOT NULL,
  state TEXT NOT NULL, receipt TEXT NOT NULL
);
CREATE UNIQUE INDEX docs_image_active_document ON docs_image_operations(document_id)
  WHERE state IN ('reviewing','writing','uncertain');

CREATE TABLE docs_semantic_evidence (digest TEXT PRIMARY KEY, bytes INTEGER NOT NULL, data BLOB NOT NULL);
CREATE TABLE docs_semantic_snapshots (id TEXT PRIMARY KEY, subject TEXT NOT NULL, account TEXT NOT NULL, thread TEXT NOT NULL,
  created INTEGER NOT NULL, expires INTEGER NOT NULL, evidence_digest TEXT NOT NULL, bytes INTEGER NOT NULL, data BLOB NOT NULL, model_digest TEXT NOT NULL);
CREATE TABLE docs_semantic_cursors (id TEXT PRIMARY KEY, snapshot TEXT NOT NULL, expires INTEGER NOT NULL, state TEXT NOT NULL);
CREATE TABLE docs_semantic_pins (snapshot TEXT NOT NULL, owner TEXT NOT NULL, expires INTEGER NOT NULL, PRIMARY KEY(snapshot,owner));
CREATE TABLE docs_semantic_delivery (id TEXT PRIMARY KEY, snapshot TEXT NOT NULL, data TEXT NOT NULL);
CREATE INDEX docs_semantic_owner ON docs_semantic_snapshots(subject,thread);
